/* HCM Lite — plain JavaScript frontend. No React, JSX, or frontend framework. */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const uid = () => 'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
  const money = n => new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:0}).format(Number(n)||0);
  const get = (k, fallback) => { try { const v=localStorage.getItem('hcm_'+k); return v===null?fallback:JSON.parse(v); } catch { return fallback; } };
  const save = (k,v) => localStorage.setItem('hcm_'+k,JSON.stringify(v));
  const iconPaths = {
    dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="4" rx="1.5"/><rect x="14" y="10" width="7" height="11" rx="1.5"/><rect x="3" y="13" width="7" height="8" rx="1.5"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>', wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 14h2"/>', building:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 21V9h6v12M7 7h.01M12 5h.01M17 7h.01M7 12h.01M17 12h.01"/>', bot:'<rect x="4" y="8" width="16" height="12" rx="3"/><path d="M12 4v4M9 13h.01M15 13h.01M9 17h6"/><path d="M2 13v2M22 13v2"/>', megaphone:'<path d="m3 11 18-5v12L3 13zM11 15l2 6H8l-2-7"/>', audit:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>', settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.8 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.8-1l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.8-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.8 1l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1 0 2z" transform="translate(-1 -1)"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>', plus:'<path d="M12 5v14M5 12h14"/>', chevron:'<path d="m9 18 6-6-6-6"/>', down:'<path d="m7 10 5 5 5-5"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', x:'<path d="m18 6-12 12M6 6l12 12"/>', bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>', moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>', arrow:'<path d="M7 17 17 7M7 7h10v10"/>', check:'<path d="m5 12 4 4L19 6"/>', download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>', send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>', spark:'<path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-2-5.8L4 11l6-2.2zM19 14l1.2 2.8L23 18l-2.8 1.2L19 22l-1.2-2.8L15 18l2.8-1.2z"/>', help:'<circle cx="12" cy="12" r="10"/><path d="M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3M12 17h.01"/>', filter:'<path d="M4 7h16M7 12h10m-7 5h4"/>', edit:'<path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/>', trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m4 4v6m6-6v6"/>', location:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>', file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h8"/>', arrowRight:'<path d="M5 12h14m-7-7 7 7-7 7"/>', checkCircle:'<circle cx="12" cy="12" r="10"/><path d="m8 12 3 3 5-6"/>', alert:'<circle cx="12" cy="12" r="10"/><path d="M12 8v4m0 4h.01"/>', activity:'<path d="M3 12h4l3-9 4 18 3-9h4"/>', calendarPlus:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m9 4h6m-3-3v6"/>'
  };
  const I = (name,size=16) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.file}</svg>`;
  const navGroups=[{label:'WORKSPACE',items:[['Dashboard','dashboard'],['Employees','users'],['Attendance','clock'],['Leave management','calendar'],['Payroll','wallet']]},{label:'ORGANIZATION',items:[['Departments & roles','building'],['Announcements','megaphone'],['AI assistant','bot']]},{label:'SYSTEM',items:[['Audit log','audit'],['Settings','settings']]}];
  const initialCompany={name:'',officeStart:'09:00',grace:15,weekend:'Saturday, Sunday',radius:150,location:'',leaveAnnual:14,leaveSick:8,leaveCasual:10};
  const state={role:'Admin',page:'Dashboard',mobileOpen:false,collapsed:false,dark:false,company:get('company',null),setupDone:localStorage.getItem('hcm_setup')==='yes',employees:get('employees',[]),leaves:get('leaves',[]),attendance:get('attendance',[]),announcements:get('announcements',[]),audit:get('audit',[]),query:'',filter:'All departments',leaveTab:'All requests',dateRange:'This month',modal:'',toast:'',messages:[{from:'ai',text:'Hi! I’m your HCM assistant. I can help with attendance rules, leave policies, and your people operations data.'}],settingsForm:null};
  state.settingsForm={...initialCompany,...(state.company||{})};
  const departments=()=>['All departments',...new Set(state.employees.map(e=>e.department).filter(Boolean))];
  const presentToday=()=>state.attendance.filter(a=>a.date===today()&&a.status!=='Checked out').length;
  const onLeave=()=>state.leaves.filter(l=>l.status==='Approved'&&l.start<=today()&&l.end>=today()).length;
  const lateToday=()=>state.attendance.filter(a=>a.date===today()&&a.status==='Late').length;
  const pendingLeaves=()=>state.leaves.filter(l=>l.status==='Pending').length;
  const audit=(action,detail='')=>{state.audit.unshift({id:uid(),date:new Date().toLocaleString(),actor:state.role,action,detail});save('audit',state.audit);};
  const notify=msg=>{state.toast=msg;renderToast();clearTimeout(notify.timer);notify.timer=setTimeout(()=>{state.toast='';renderToast();},3200);};
  const statusPill=s=>`<span class="status-pill ${esc(String(s).toLowerCase().replaceAll(' ','-'))}">${esc(s)}</span>`;
  const avatar=(name,tone='green')=>`<div class="avatar avatar-${tone}">${esc((name||'U').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div>`;
  const pageHeading=(eyebrow,title,subtitle,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${action}</div></div>`;
  const btn=(label,cls='btn-secondary',icon='')=>`<button class="btn ${cls}" data-action="${label==='Add employee'?'add-employee':label==='New leave request'?'add-leave':label==='Post announcement'?'add-announcement':'noop'}">${icon?I(icon,15):''}${label}</button>`;
  function shell(){return `<div class="app-shell ${state.dark?'dark':''}"><aside class="sidebar ${state.collapsed?'collapsed':''} ${state.mobileOpen?'mobile-show':''}"><div class="sidebar-top"><div class="brand"><div class="brand-mark">${I('activity',21)}</div><span>hcm <b>lite</b></span></div><button class="icon-btn sidebar-close" data-action="close-menu">${I('x',18)}</button></div><div class="workspace-switch"><div class="company-avatar">${esc((state.company?.name||'H').slice(0,1).toUpperCase())}</div><div class="workspace-copy"><b>${esc(state.company?.name||'Your workspace')}</b><span>People operations</span></div>${I('down',14)}</div><nav class="nav-scroll">${navGroups.map(g=>`<div class="nav-group"><div class="nav-label">${g.label}</div>${g.items.map(([name,ic])=>`<button class="nav-item ${state.page===name?'active':''}" data-page="${name}" title="${name}">${I(ic,17)}<span>${name}</span>${name==='Leave management'&&pendingLeaves()?`<span class="nav-count">${pendingLeaves()}</span>`:''}</button>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom">${!state.collapsed?`<div class="help-card"><div class="help-icon">${I('help',17)}</div><b>Need a hand?</b><p>Explore the HCM Lite demo and discover your workspace.</p><button data-action="help">Help centre ${I('arrowRight',13)}</button></div>`:''}<div class="profile-mini">${avatar('Ali Hasan','green')}<div class="profile-copy"><b>Ali Hasan</b><span>${esc(state.role)} workspace</span></div><button class="dots-btn" data-action="profile-menu">•••</button></div><button class="collapse-btn" data-action="collapse">${I(state.collapsed?'arrowRight':'chevron',14)} ${state.collapsed?'':'Collapse sidebar'}</button></div></aside>${state.mobileOpen?'<div class="mobile-overlay" data-action="close-menu"></div>':''}<main class="main-area"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="open-menu">${I('menu',19)}</button><div class="breadcrumbs"><span>Workspace</span>${I('chevron',13)}<b>${esc(state.page)}</b></div></div><div class="topbar-actions"><label class="role-switch"><span>View as</span><select id="role-select"><option ${state.role==='Admin'?'selected':''}>Admin</option><option ${state.role==='HR'?'selected':''}>HR</option><option ${state.role==='Employee'?'selected':''}>Employee</option></select>${I('down',12)}</label><button class="icon-btn" data-action="theme" title="Toggle dark mode">${I(state.dark?'sun':'moon',17)}</button><button class="icon-btn notification-btn" data-action="notifications" title="Notifications">${I('bell',17)}<i></i></button>${avatar('Ali Hasan','green').replace('class="avatar avatar-green"','class="avatar avatar-green top-avatar"')}</div></header><section class="page-content">${renderPage()}</section><footer class="footer"><span>© 2025 HCM Lite. Built for better people operations.</span><span><i class="status-dot"></i> Frontend demo <span class="footer-divider">·</span> <button data-action="help">Help & support</button></span></footer></main>${state.modal?renderModal():''}<div id="toast-host"></div></div>`;}
  function empty(icon,title,text,action='',page=''){return `<div class="empty-state"><div class="empty-icon">${I(icon,20)}</div><b>${title}</b><p>${text}</p>${action?`<button class="btn btn-secondary btn-small" data-page="${page}">${action} ${I('arrowRight',13)}</button>`:''}</div>`;}
  function kpi(label,value,sub,ic,tone){return `<div class="kpi-card"><div class="kpi-top"><span>${label}</span><div class="kpi-icon ${tone}">${I(ic,18)}</div></div><div class="kpi-value">${value}</div><div class="kpi-sub">${sub}</div></div>`;}
  function svgChart(){const w=520,h=160, left=28,right=12,top=12,bottom=25, cw=w-left-right,ch=h-top-bottom;const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const vals=days.map((_,i)=>{const items=state.attendance.filter(a=>{const d=new Date(a.date+'T12:00:00');return (d.getDay()+6)%7===i});return {present:items.filter(a=>['Present','Checked out'].includes(a.status)).length,late:items.filter(a=>a.status==='Late').length}});const max=Math.max(3,...vals.map(v=>v.present+v.late));const pts=key=>vals.map((v,i)=>`${left+i*cw/6},${top+ch-(v[key]/max)*ch}`).join(' ');let grid='';for(let i=0;i<4;i++){const y=top+ch*i/3;grid+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="var(--border)" stroke-dasharray="3 4"/>`;grid+=`<text x="${left-9}" y="${y+3}" text-anchor="end">${Math.round(max*(1-i/3))}</text>`;}const labels=days.map((d,i)=>`<text x="${left+i*cw/6}" y="${h-5}" text-anchor="middle">${d}</text>`).join('');return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Attendance by weekday">${grid}<polyline points="${pts('present')}" fill="none" stroke="#31866b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${pts('late')}" fill="none" stroke="#e3a34c" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>${labels}</svg>`;}
  function dashboard(){const employee=state.role==='Employee';const total=state.employees.length;const welcome=employee?'Your day at a glance':state.role==='Admin'?'Your people, all in one place':'Let’s make today productive';const subtitle=employee?'Here’s your personal work snapshot for today.':`Here’s what’s happening at ${state.company?.name||'your company'} today.`;const act=`<button class="btn btn-secondary date-button" data-action="date-range">${I('calendar',15)}${state.dateRange}${I('down',13)}</button>${!employee?`<button class="btn btn-primary" data-action="add-employee">${I('plus',15)} Add employee</button>`:''}`;const cards=employee?[kpi('Hours this week',state.attendance.length?'—':'0h / 40h','Weekly target','clock','green'),kpi('Late arrivals',state.attendance.filter(a=>a.status==='Late').length,'Recorded attendance','activity','orange'),kpi('Leave requests',state.leaves.length,`${state.leaves.filter(l=>l.status==='Approved').length} approved`,'calendar','purple'),kpi('Last payslip','—','No payslip yet','wallet','blue')]:[kpi('Total employees',total,total?`${state.employees.filter(e=>e.status==='Active').length} active employees`:'No employees added yet','users','green'),kpi('Present today',presentToday(),'Check-ins recorded','calendar','blue'),kpi('On leave',onLeave(),'Approved leave today','calendar','purple'),kpi('Late arrivals',lateToday(),pendingLeaves()?`${pendingLeaves()} leave approvals pending`:'Within attendance records','clock','orange')];
    const recent=state.attendance.slice(0,4);const leaves=state.leaves.filter(l=>l.status==='Pending').slice(0,3);const anns=state.announcements.slice(0,2);return `${pageHeading(employee?'YOUR WORKSPACE':state.role==='Admin'?'COMPANY OVERVIEW':'PEOPLE OPERATIONS',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}${employee?'':' 👋'}`,subtitle,act)}<div class="welcome-banner"><div class="welcome-icon">${I('spark',19)}</div><div><b>${welcome}</b><p>${employee?'Check your attendance, review leave balance, or ask your assistant for help.':!total?'Your workspace is ready. Add your first employee to start bringing your people data to life.':'Your workspace is up to date. Review today’s attendance and pending team actions.'}</p></div><button class="banner-link" data-page="${employee?'AI assistant':'Employees'}">${employee?'Ask assistant':'Explore people'} ${I('arrowRight',15)}</button></div><div class="kpi-grid">${cards.join('')}</div><div class="dashboard-grid"><div class="panel attendance-chart-panel"><div class="panel-heading"><div><h3>Attendance overview</h3><p>Recorded check-ins by day</p></div><button class="icon-btn" data-page="Attendance">${I('arrow',17)}</button></div>${state.attendance.length?`<div class="chart-area">${svgChart()}</div>`:empty('activity','Your attendance story starts here','Once employees check in, daily attendance trends will appear here.','View attendance','Attendance')}</div><div class="panel quick-panel"><div class="panel-heading"><div><h3>Quick actions</h3><p>Common tasks, right at your fingertips</p></div></div><div class="quick-actions"><button class="quick-action" data-action="add-employee"><span class="quick-icon">${I('users',16)}</span>Add a new employee ${I('chevron',14).replace('<svg','<svg class="quick-arrow"')}</button><button class="quick-action" data-action="add-leave"><span class="quick-icon qi-1">${I('calendar',16)}</span>Submit leave request ${I('chevron',14).replace('<svg','<svg class="quick-arrow"')}</button><button class="quick-action" data-page="Attendance"><span class="quick-icon qi-2">${I('clock',16)}</span>View attendance ${I('chevron',14).replace('<svg','<svg class="quick-arrow"')}</button><button class="quick-action" data-action="add-announcement"><span class="quick-icon qi-3">${I('megaphone',16)}</span>Post an announcement ${I('chevron',14).replace('<svg','<svg class="quick-arrow"')}</button></div></div><div class="panel recent-panel"><div class="panel-heading"><div><h3>Recent attendance</h3><p>Your latest attendance activity</p></div><button class="text-link" data-page="Attendance">View all ${I('arrowRight',13)}</button></div>${recent.length?`<div class="table-scroll"><table class="mini-table"><thead><tr><th>EMPLOYEE</th><th>DATE</th><th>CHECK IN</th><th>STATUS</th></tr></thead><tbody>${recent.map(a=>`<tr><td><div class="employee-cell">${avatar(a.name)}<div><b>${esc(a.name)}</b><span>${esc(a.employeeCode||'Employee')}</span></div></div></td><td>${esc(a.date)}</td><td>${esc(a.inTime)}</td><td>${statusPill(a.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('clock','No attendance records yet','Check-ins will appear here after an employee is registered and attendance is recorded.','Go to attendance','Attendance')}</div><div class="panel leave-panel"><div class="panel-heading"><div><h3>Pending leave requests</h3><p>Requests waiting for review</p></div><button class="text-link" data-page="Leave management">View all ${I('arrowRight',13)}</button></div>${leaves.length?`<div class="leave-mini-list">${leaves.map(l=>{const e=state.employees.find(x=>x.id===l.employee);return `<div class="leave-mini">${avatar(e?.name||'Employee','purple')}<div class="leave-mini-copy"><b>${esc(e?.name||'Employee')}</b><span>${esc(l.type)} leave · ${esc(l.start)} to ${esc(l.end)}</span></div>${statusPill(l.status)}</div>`}).join('')}</div>`:empty('calendar','All caught up!','There are no pending leave requests to review.')}</div><div class="panel ai-insight-panel"><div class="ai-panel-top"><div class="ai-heading-icon">${I('spark',18)}</div><div><h3>AI-powered insights</h3><p>A smarter view of your people data</p></div><span class="ai-label">AI ASSISTANT</span></div><div class="insight-empty"><p>Get a quick summary of attendance patterns, leave trends, and workforce activity using your workspace records.</p><button class="btn btn-secondary btn-small" data-action="ai-summary">${I('spark',13)} Generate summary</button></div></div><div class="panel announcement-panel"><div class="panel-heading"><div><h3>Latest announcements</h3><p>Keep your team in the loop</p></div><button class="text-link" data-page="Announcements">View all ${I('arrowRight',13)}</button></div>${anns.length?anns.map(a=>`<div class="announcement-item"><div class="announcement-bullet">${I('megaphone',14)}</div><div><b>${esc(a.title)}</b><p>${esc(a.body)}</p><span>${esc(a.date)} · ${esc(a.author||'Admin')}</span></div></div>`).join(''):empty('megaphone','No announcements yet','Share company updates and important news with your team.','Create announcement','Announcements')}</div></div>`;}
  function toolbar(extra=''){return `<div class="toolbar"><label class="search-field">${I('search',16)}<input id="search-input" placeholder="Search by name, email or department..." value="${esc(state.query)}"></label>${extra}</div>`;}
  function employeesPage(){const list=state.employees.filter(e=>(`${e.name} ${e.email} ${e.department} ${e.designation} ${e.code}`).toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='All departments'||e.department===state.filter));const action=`<button class="btn btn-secondary" data-action="export-csv">${I('download',15)} Export CSV</button><button class="btn btn-primary" data-action="add-employee">${I('plus',15)} Add employee</button>`;return `${pageHeading('PEOPLE DIRECTORY','Employees','Manage your people, roles, and employee records.',action)}<div class="kpi-grid compact-kpis">${kpi('Total employees',state.employees.length,'All registered employees','users','green')}${kpi('Active employees',state.employees.filter(e=>e.status==='Active').length,'Currently active','checkCircle','blue')}${kpi('Departments',new Set(state.employees.map(e=>e.department)).size,'Across your organization','building','purple')}${kpi('Monthly basic payroll',money(state.employees.reduce((s,e)=>s+Number(e.salary||0),0)),'Before allowances & deductions','wallet','orange')}</div>${toolbar(`<label class="filter-select">${I('filter',14)}<select id="department-filter">${departments().map(d=>`<option ${d===state.filter?'selected':''}>${esc(d)}</option>`).join('')}</select></label><span class="results-count">${list.length} employee${list.length===1?'':'s'}</span>`)}<div class="panel table-panel"><div class="panel-heading"><div><h3>All employees</h3><p>Employee information and employment details</p></div><span class="small-tag">${list.length} records</span></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>EMPLOYEE ID</th><th>DEPARTMENT</th><th>DESIGNATION</th><th>JOINING DATE</th><th>MONTHLY BASIC</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${list.map(e=>`<tr><td><div class="employee-cell">${avatar(e.name)}<div><b>${esc(e.name)}</b><span>${esc(e.email)}</span></div></div></td><td>${esc(e.code||'—')}</td><td>${esc(e.department||'—')}</td><td>${esc(e.designation||'—')}</td><td>${esc(e.joinDate||'—')}</td><td>${money(e.salary)}</td><td>${statusPill(e.status||'Active')}</td><td><div class="row-actions"><button class="icon-btn" title="Edit employee" data-action="edit-employee" data-id="${e.id}">${I('edit',14)}</button><button class="icon-btn" title="Remove employee" data-action="delete-employee" data-id="${e.id}">${I('trash',14)}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('users',state.query?'No matching employees':'Your employee directory is empty',state.query?'Try a different name, email, or department.':'Add your first employee to start building your organization.','Add employee','Employees')}</div><div class="info-strip">${I('help',17)}<div><b>Employee records stay in this browser for now</b><p>This frontend prototype uses local browser storage. Secure multi-user access and shared records will be added with the backend.</p></div></div>`;}
  function attendancePage(){const rows=state.attendance.filter(a=>(`${a.name} ${a.date} ${a.status}`).toLowerCase().includes(state.query.toLowerCase()));return `${pageHeading('TIME & ATTENDANCE','Attendance','Review daily check-ins, check-outs, and attendance status.',`<button class="btn btn-secondary" data-action="export-attendance">${I('download',15)} Export CSV</button>`)}<div class="kpi-grid compact-kpis">${kpi('Present today',presentToday(),'Recorded check-ins','checkCircle','green')}${kpi('Late arrivals',lateToday(),'Past grace period','clock','orange')}${kpi('On leave',onLeave(),'Approved leave today','calendar','purple')}${kpi('Total records',state.attendance.length,'All recorded attendance','activity','blue')}</div><div class="welcome-banner"><div class="welcome-icon">${I('clock',18)}</div><div><b>Attendance demo controls</b><p>For this frontend demo, check-in/out actions use the first registered employee. Real camera, GPS and geofence validation require backend integration.</p></div><button class="btn btn-primary btn-small" data-action="check-in">Check in</button><button class="btn btn-secondary btn-small" data-action="check-out">Check out</button></div>${toolbar(`<label class="filter-select">${I('filter',14)}<select id="attendance-filter"><option>All statuses</option><option>Present</option><option>Late</option><option>Checked out</option></select></label><span class="results-count">${rows.length} records</span>`)}<div class="panel table-panel"><div class="panel-heading"><div><h3>Attendance records</h3><p>Recorded employee attendance</p></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>DATE</th><th>CHECK IN</th><th>CHECK OUT</th><th>STATUS</th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="employee-cell">${avatar(a.name)}<div><b>${esc(a.name)}</b><span>${esc(a.employeeCode||'Employee')}</span></div></div></td><td>${esc(a.date)}</td><td>${esc(a.inTime||'—')}</td><td>${esc(a.outTime||'—')}</td><td>${statusPill(a.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('clock','No attendance records yet','Attendance records will appear here after you record an employee check-in.')}</div>`;}
  function leavePage(){let list=state.leaves.filter(l=>(`${state.employees.find(e=>e.id===l.employee)?.name||''} ${l.type} ${l.reason} ${l.status}`).toLowerCase().includes(state.query.toLowerCase()));if(state.leaveTab!=='All requests')list=list.filter(l=>l.status===state.leaveTab);return `${pageHeading('TIME OFF','Leave management','Manage leave requests, approvals, and leave policies.',`<button class="btn btn-primary" data-action="add-leave">${I('plus',15)} New leave request</button>`)}<div class="leave-balance-grid"><div class="balance-card"><span>Annual leave quota</span><b>${state.company?.leaveAnnual??14} days</b><small>Per employee / year</small></div><div class="balance-card"><span>Sick leave quota</span><b>${state.company?.leaveSick??8} days</b><small>Per employee / year</small></div><div class="balance-card"><span>Casual leave quota</span><b>${state.company?.leaveCasual??10} days</b><small>Per employee / year</small></div><div class="balance-card"><span>Pending approvals</span><b>${pendingLeaves()}</b><small>Awaiting HR review</small></div></div>${toolbar(`<div class="tabs">${['All requests','Pending','Approved','Rejected'].map(t=>`<button class="${state.leaveTab===t?'selected':''}" data-leave-tab="${t}">${t}</button>`).join('')}</div>`)}<div class="panel table-panel"><div class="panel-heading"><div><h3>Leave requests</h3><p>Requests and their current approval status</p></div><span class="small-tag">${list.length} requests</span></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>LEAVE TYPE</th><th>DATES</th><th>REASON</th><th>STATUS</th><th>REVIEW</th></tr></thead><tbody>${list.map(l=>{const e=state.employees.find(x=>x.id===l.employee);return `<tr><td><div class="employee-cell">${avatar(e?.name||'Employee','purple')}<div><b>${esc(e?.name||'Employee')}</b><span>${esc(e?.email||'Employee record unavailable')}</span></div></div></td><td>${esc(l.type)}</td><td>${esc(l.start)}<br><span class="muted">to ${esc(l.end)}</span></td><td class="reason-cell" title="${esc(l.reason)}">${esc(l.reason||'—')}</td><td>${statusPill(l.status)}</td><td>${l.status==='Pending'?`<div class="row-actions"><button class="approve-btn" data-action="decide-leave" data-id="${l.id}" data-status="Approved" title="Approve">${I('check',14)}</button><button class="reject-btn" data-action="decide-leave" data-id="${l.id}" data-status="Rejected" title="Reject">${I('x',14)}</button></div>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:empty('calendar','No leave requests found','Leave requests submitted by employees will appear here.','Create leave request','Leave management')}</div><div class="info-strip">${I('help',17)}<div><b>Leave policy preview</b><p>Weekend and holiday exclusions, overlap checks, and quota validation need to be enforced by the backend before production use.</p></div></div>`;}
  function payrollPage(){const total=state.employees.reduce((s,e)=>s+Number(e.salary||0)*1.5,0);return `${pageHeading('COMPENSATION','Payroll Lite','Preview salary components and monthly payroll estimates.',`<button class="btn btn-secondary" data-action="export-payroll">${I('download',15)} Export CSV</button>`)}<div class="kpi-grid compact-kpis">${kpi('Employees',state.employees.length,'In this workspace','users','green')}${kpi('Basic salary total',money(state.employees.reduce((s,e)=>s+Number(e.salary||0),0)),'Monthly basic salaries','wallet','blue')}${kpi('Estimated gross',money(total),'Basic + 50% allowances','trendingUp','purple')}${kpi('Payroll status','Draft','Not finalized','file','orange')}</div><div class="panel table-panel"><div class="panel-heading"><div><h3>Monthly payroll preview</h3><p>Estimates use the simplified HCM Lite demo formula.</p></div><input class="month-input" type="month" id="payroll-month" value="${today().slice(0,7)}"></div>${state.employees.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>BASIC SALARY</th><th>HRA (40%)</th><th>MEDICAL (10%)</th><th>EST. GROSS</th><th>STATUS</th></tr></thead><tbody>${state.employees.map(e=>{const basic=Number(e.salary)||0;return `<tr><td><div class="employee-cell">${avatar(e.name)}<div><b>${esc(e.name)}</b><span>${esc(e.code||'Employee')}</span></div></div></td><td>${money(basic)}</td><td>${money(basic*.4)}</td><td>${money(basic*.1)}</td><td><b>${money(basic*1.5)}</b></td><td>${statusPill('Draft')}</td></tr>`}).join('')}</tbody></table></div>`:empty('wallet','No payroll data available','Add employee records with basic salaries to see estimated payroll components.','Add employee','Employees')}</div><div class="info-strip">${I('alert',17)}<div><b>Payroll preview only — not a finalized payslip</b><p>This demo shows basic salary + 40% HRA + 10% medical allowance. Tax, absence deductions, proration, locked payroll runs, and actual PDF payslips must be implemented and verified on the server.</p></div></div>`;}
  function departmentsPage(){const groups={};state.employees.forEach(e=>{const d=e.department||'Unassigned';groups[d]??=[];groups[d].push(e)});return `${pageHeading('ORGANIZATION','Departments & roles','Explore department headcount and employee roles.')}<div class="kpi-grid compact-kpis">${kpi('Departments',Object.keys(groups).length,'With registered employees','building','green')}${kpi('Employees assigned',state.employees.filter(e=>e.department).length,'With a department','users','blue')}${kpi('Unassigned',state.employees.filter(e=>!e.department).length,'Need department assignment','alert','orange')}${kpi('Roles',new Set(state.employees.map(e=>e.designation).filter(Boolean)).size,'Unique designations','shield','purple')}</div><div class="announcement-grid">${Object.entries(groups).map(([name,emps])=>`<div class="panel announcement-card"><div class="announcement-card-icon">${I('building',18)}</div><span class="announcement-meta">DEPARTMENT</span><h3>${esc(name)}</h3><p>${emps.length} employee${emps.length===1?'':'s'} · ${[...new Set(emps.map(e=>e.designation).filter(Boolean))].map(esc).join(', ')||'No designations recorded'}</p><div class="leave-mini-list" style="padding:10px 0 0">${emps.slice(0,4).map(e=>`<div class="leave-mini">${avatar(e.name)}<div class="leave-mini-copy"><b>${esc(e.name)}</b><span>${esc(e.designation||'Team member')}</span></div></div>`).join('')}</div></div>`).join('')}${!Object.keys(groups).length?`<div class="panel" style="grid-column:1/-1">${empty('building','No departments to show','Register employees to populate department and role information.','Add employee','Employees')}</div>`:''}</div><div class="info-strip">${I('help',17)}<div><b>Role access preview</b><p>The Admin, HR, and Employee selector previews role-based UI. Real authorization must be enforced on every backend API request.</p></div></div>`;}
  function announcementsPage(){return `${pageHeading('TEAM COMMUNICATION','Announcements','Share important updates and keep your team informed.',`<button class="btn btn-primary" data-action="add-announcement">${I('plus',15)} Post announcement</button>`)}${state.announcements.length?`<div class="announcement-grid">${state.announcements.map(a=>`<article class="panel announcement-card"><div class="announcement-card-icon">${I('megaphone',18)}</div><span class="announcement-meta">${esc(a.date)} · ${esc(a.author||'Admin')}</span><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p></article>`).join('')}</div>`:`<div class="panel empty-large">${empty('megaphone','No announcements yet','When you publish an announcement, it will appear here for your team.','Create announcement','Announcements')}</div>`}`;}
  function aiPage(){return `${pageHeading('AI WORKSPACE','AI assistant','Ask about attendance, leave policies, and your workspace data.')}<div class="ai-layout"><div class="panel chat-panel"><div class="chat-header"><div class="ai-heading-icon">${I('bot',19)}</div><div><b>HCM assistant</b><span><i class="status-dot"></i> Frontend demo mode</span></div><span class="ai-label">AI ASSISTANT</span></div><div class="chat-messages" id="chat-messages">${state.messages.map(m=>`<div class="chat-row ${m.from==='user'?'user':''}">${m.from==='ai'?`<div class="chat-avatar">${I('spark',14)}</div>`:''}<div class="chat-bubble">${esc(m.text).replace(/\n/g,'<br>')}${m.from==='ai'?'<small>Demo response · Verify important decisions with HR</small>':''}</div></div>`).join('')}</div><div class="chat-suggestions"><span>TRY ASKING</span>${['Who is on leave today?','What are the attendance rules?','How does payroll work?'].map(q=>`<button data-chat-prompt="${esc(q)}">${I('spark',12)} ${q}</button>`).join('')}</div><form class="chat-input-row" id="chat-form"><input id="chat-input" placeholder="Ask a question about your workspace..." autocomplete="off"><button class="send-btn" type="submit" aria-label="Send message">${I('send',17)}</button></form></div><aside class="ai-side"><div class="panel ai-about"><div class="ai-heading-icon">${I('spark',18)}</div><h3>Your people operations copilot</h3><p>Ask questions in plain language. This frontend demo answers using the data currently saved in this browser.</p><ul><li>${I('checkCircle',14)} Attendance summaries</li><li>${I('checkCircle',14)} Leave policy guidance</li><li>${I('checkCircle',14)} Workforce headcount</li><li>${I('checkCircle',14)} Payroll formula overview</li></ul></div><div class="panel policy-card"><h3>Workspace policies</h3><div><b>Office start</b><span>${esc(state.company?.officeStart||'09:00')}</span></div><div><b>Grace period</b><span>${Number(state.company?.grace??15)} minutes</span></div><div><b>Annual leave</b><span>${Number(state.company?.leaveAnnual??14)} days</span></div><div><b>Sick leave</b><span>${Number(state.company?.leaveSick??8)} days</span></div></div></aside></div>`;}
  function auditPage(){return `${pageHeading('SYSTEM ACTIVITY','Audit log','A local preview of actions performed in this browser.',`<button class="btn btn-secondary" data-action="export-audit">${I('download',15)} Export CSV</button>`)}<div class="panel table-panel"><div class="panel-heading"><div><h3>Activity history</h3><p>Demo actions recorded during this browser session</p></div><span class="small-tag">${state.audit.length} events</span></div>${state.audit.length?`<div class="table-scroll"><table><thead><tr><th>DATE & TIME</th><th>ACTOR</th><th>ACTION</th><th>DETAIL</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.detail||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('audit','No activity recorded yet','Actions like adding employees, submitting leave, and updating settings will appear here.')}</div><div class="info-strip">${I('alert',17)}<div><b>Not a production audit log</b><p>Browser storage can be edited or deleted by a user. Production audit events must be written and protected on the server.</p></div></div>`;}
  function settingsPage(){const c=state.settingsForm;return `${pageHeading('WORKSPACE CONFIGURATION','Settings','Configure your company profile, attendance rules, and leave policy.')}<div class="settings-layout"><div class="settings-nav"><div class="settings-nav-item active">${I('building',15)} Company profile</div><div class="settings-nav-item">${I('clock',15)} Attendance rules</div><div class="settings-nav-item">${I('calendar',15)} Leave policy</div><div class="settings-nav-item">${I('shield',15)} Security</div></div><form class="panel settings-form" id="settings-form"><div class="panel-heading"><div><h3>Company configuration</h3><p>These settings are stored locally in this demo.</p></div></div><label class="simple-field">Company name <em>*</em><input name="name" required value="${esc(c.name)}" placeholder="e.g. Acme Technologies"></label><div class="two-fields"><label class="simple-field">Office start time<input type="time" name="officeStart" value="${esc(c.officeStart)}"></label><label class="simple-field">Grace period (minutes)<input type="number" name="grace" min="0" max="180" value="${Number(c.grace)}"></label></div><label class="simple-field">Office address<input name="location" value="${esc(c.location)}" placeholder="Office address"></label><div class="two-fields"><label class="simple-field">GPS radius (metres)<input type="number" name="radius" min="0" value="${Number(c.radius)}"></label><label class="simple-field">Weekend days<select name="weekend"><option ${c.weekend==='Saturday, Sunday'?'selected':''}>Saturday, Sunday</option><option ${c.weekend==='Sunday'?'selected':''}>Sunday</option><option ${c.weekend==='Friday, Saturday'?'selected':''}>Friday, Saturday</option></select></label></div><div class="two-fields"><label class="simple-field">Annual leave quota (days)<input type="number" name="leaveAnnual" min="0" value="${Number(c.leaveAnnual)}"></label><label class="simple-field">Sick leave quota (days)<input type="number" name="leaveSick" min="0" value="${Number(c.leaveSick)}"></label></div><label class="simple-field">Casual leave quota (days)<input type="number" name="leaveCasual" min="0" value="${Number(c.leaveCasual)}"></label><div class="settings-save-row"><span class="muted">${I('checkCircle',14)} Changes apply to this browser demo</span><button class="btn btn-primary" type="submit">Save settings ${I('arrowRight',14)}</button></div></form></div><div class="panel danger-panel"><div><b>Reset demo workspace</b><p>Delete company settings, employees, attendance, leave requests and announcements saved in this browser.</p></div><button class="btn btn-danger" data-action="reset-demo">${I('trash',14)} Reset demo</button></div>`;}
  function renderPage(){switch(state.page){case'Dashboard':return dashboard();case'Employees':return employeesPage();case'Attendance':return attendancePage();case'Leave management':return leavePage();case'Payroll':return payrollPage();case'Departments & roles':return departmentsPage();case'Announcements':return announcementsPage();case'AI assistant':return aiPage();case'Audit log':return auditPage();case'Settings':return settingsPage();default:return dashboard();}}
  function setupPage(){const c=state.settingsForm;return `<div class="setup-screen"><section class="setup-art"><div class="brand brand-light"><div class="brand-mark">${I('activity',21)}</div><span>hcm <b>lite</b></span></div><div class="setup-art-content"><div class="eyebrow">HUMAN CAPITAL MANAGEMENT</div><h1>Your people.<br>Your biggest strength.</h1><p>A simpler way to manage your workforce, attendance, leave, and payroll — all in one thoughtfully designed workspace.</p><div class="setup-pills"><span>${I('users',15)} People first</span><span>${I('activity',15)} Insight driven</span><span>${I('shield',15)} Built for teams</span></div></div><div class="setup-art-footer">HCM LITE · PEOPLE OPERATIONS PLATFORM</div></section><section class="setup-form-wrap"><form class="setup-form" id="setup-form"><div class="step-tag">GET STARTED <span>STEP 1 OF 1</span></div><h2>Set up your workspace</h2><p class="muted">Start by telling us a little about your organization. You can change these details later.</p><label class="simple-field">Company name <em>*</em><input name="name" required autofocus value="${esc(c.name)}" placeholder="e.g. Acme Technologies"></label><div class="two-fields"><label class="simple-field">Office start time<input type="time" name="officeStart" value="${esc(c.officeStart||'09:00')}"></label><label class="simple-field">Grace period (minutes)<input type="number" name="grace" min="0" max="180" value="${Number(c.grace??15)}"></label></div><label class="simple-field">Office address<input name="location" value="${esc(c.location)}" placeholder="Office address (optional)"></label><div class="two-fields"><label class="simple-field">GPS radius (metres)<input name="radius" type="number" min="0" value="${Number(c.radius??150)}"></label><label class="simple-field">Weekend days<select name="weekend"><option ${c.weekend==='Saturday, Sunday'?'selected':''}>Saturday, Sunday</option><option ${c.weekend==='Sunday'?'selected':''}>Sunday</option><option ${c.weekend==='Friday, Saturday'?'selected':''}>Friday, Saturday</option></select></label></div><div class="setup-note">${I('shield',17)}<div><b>Secure by design, ready to grow</b><br>This is frontend setup only. Real accounts, access control, and company data security will be implemented in the backend phase.</div></div><button class="btn btn-primary btn-wide" type="submit">Create company workspace ${I('arrowRight',15)}</button><p class="form-foot">HCM Lite · Frontend prototype</p></form></section></div>`;}
  function render(){const root=$('#app');root.innerHTML=state.setupDone?shell():setupPage();if(state.page==='AI assistant'){const box=$('#chat-messages');if(box)box.scrollTop=box.scrollHeight;}renderToast();}
  function renderToast(){const host=$('#toast-host');if(!host)return;host.innerHTML=state.toast?`<div class="toast">${I('checkCircle',17)}<span>${esc(state.toast)}</span><button data-action="dismiss-toast">${I('x',14)}</button></div>`:'';}
  function field(label,name,placeholder='',type='text',required=false,value=''){return `<label class="simple-field">${label}${required?' <em>*</em>':''}<input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${required?'required':''}></label>`;}
  function renderModal(){if(state.modal==='employee'){const e=state.editingEmployee||{};return `<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>${e.id?'Edit employee':'Add an employee'}</h2><p>Enter employee details to add them to your directory.</p></div><button class="icon-btn" data-action="close-modal">${I('x',18)}</button></div><form class="modal-form" id="employee-form"><div class="form-grid">${field('Full name','name','e.g. Ayesha Khan','text',true,e.name)}${field('Work email','email','name@company.com','email',true,e.email)}<label class="simple-field">Department<select name="department"><option ${e.department==='Engineering'?'selected':''}>Engineering</option><option ${e.department==='Human Resources'?'selected':''}>Human Resources</option><option ${e.department==='Operations'?'selected':''}>Operations</option><option ${e.department==='Marketing'?'selected':''}>Marketing</option><option ${e.department==='Finance'?'selected':''}>Finance</option><option ${e.department==='Sales'?'selected':''}>Sales</option></select></label>${field('Designation','designation','e.g. Software Engineer','text',false,e.designation)}${field('Phone','phone','+92 300 0000000','tel',false,e.phone)}${field('Monthly basic salary (PKR)','salary','85000','number',false,e.salary)}${field('Joining date','joinDate','','date',false,e.joinDate||today())}</div><div class="modal-note">${I('shield',16)} In the backend version, employee registration will create a login with a temporary password.</div><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${e.id?'Save changes':'Register employee'} ${I('arrowRight',15)}</button></div></form></section></div>`;}
    if(state.modal==='leave')return `<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>New leave request</h2><p>Create a leave request for review.</p></div><button class="icon-btn" data-action="close-modal">${I('x',18)}</button></div><form class="modal-form" id="leave-form"><label class="simple-field">Employee <em>*</em><select name="employee" required><option value="">Select employee</option>${state.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><label class="simple-field">Leave type<select name="type"><option>Casual</option><option>Sick</option><option>Annual</option><option>Unpaid</option></select></label><div class="two-fields">${field('Start date','start','','date',true,today())}${field('End date','end','','date',true,today())}</div><label class="simple-field">Reason <em>*</em><textarea name="reason" required rows="3" placeholder="Share a short reason..."></textarea></label><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Submit request ${I('arrowRight',15)}</button></div></form></section></div>`;
    if(state.modal==='announcement')return `<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Post an announcement</h2><p>Share an update with your team.</p></div><button class="icon-btn" data-action="close-modal">${I('x',18)}</button></div><form class="modal-form" id="announcement-form">${field('Announcement title','title','e.g. Public holiday notice','text',true)}<label class="simple-field">Message<textarea name="body" rows="4" required placeholder="Write your announcement..."></textarea></label><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Post announcement ${I('send',15)}</button></div></form></section></div>`;
    return '';}
  function formObj(form){return Object.fromEntries(new FormData(form).entries());}
  function csvDownload(filename,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);notify('CSV export downloaded');}
  function chat(text){text=text.trim();if(!text)return;state.messages.push({from:'user',text});const q=text.toLowerCase();let answer='I’m currently running in frontend-only demo mode. Connect the backend AI service to answer using live company records.';if(q.includes('leave')&&q.includes('today'))answer=`There ${onLeave()===1?'is':'are'} ${onLeave()} approved leave request${onLeave()===1?'':'s'} covering today. This answer uses the current frontend demo records.`;else if(q.includes('headcount')||q.includes('employee'))answer=`There ${state.employees.length===1?'is':'are'} ${state.employees.length} employee${state.employees.length===1?'':'s'} registered in this workspace.`;else if(q.includes('attendance')||q.includes('present'))answer=`Today's workspace records show ${presentToday()} check-in(s), ${lateToday()} late arrival(s), and ${onLeave()} employee(s) on approved leave.`;else if(q.includes('sick'))answer=`The configured annual sick leave quota is ${state.company?.leaveSick??8} days. Individual balances require backend calculations against approved leave.`;else if(q.includes('salary')&&(/colleague|other employee|someone else/.test(q)))answer='I can’t disclose another employee’s salary. Salary information is restricted by role and data scope.';else if(q.includes('rule'))answer=`Office start is ${state.company?.officeStart||'09:00'} with a ${state.company?.grace??15}-minute grace period. Late status should be validated on the backend in production.`;else if(q.includes('payroll'))answer='The demo gross salary formula is basic salary + 40% HRA + 10% medical allowance. Tax, absence deductions and final payroll locking need backend implementation.';state.messages.push({from:'ai',text:answer});render();}
  function action(name,el,ev){switch(name){case'open-menu':state.mobileOpen=true;render();break;case'close-menu':state.mobileOpen=false;render();break;case'collapse':state.collapsed=!state.collapsed;render();break;case'theme':state.dark=!state.dark;render();break;case'add-employee':state.editingEmployee=null;state.modal='employee';render();break;case'edit-employee':state.editingEmployee=state.employees.find(e=>e.id===el.dataset.id)||null;state.modal='employee';render();break;case'add-leave':if(!state.employees.length){notify('Register an employee first');return;}state.modal='leave';render();break;case'add-announcement':state.modal='announcement';render();break;case'close-modal':state.modal='';state.editingEmployee=null;render();break;case'backdrop':if(el===ev.target){state.modal='';render();}break;case'export-csv':csvDownload('hcm-employees.csv',[['Employee code','Name','Email','Department','Designation','Phone','Salary','Status'],...state.employees.map(e=>[e.code,e.name,e.email,e.department,e.designation,e.phone,e.salary,e.status])]);break;case'export-attendance':csvDownload('hcm-attendance.csv',[['Employee','Date','Check in','Check out','Status'],...state.attendance.map(a=>[a.name,a.date,a.inTime,a.outTime,a.status])]);break;case'export-payroll':csvDownload('hcm-payroll-preview.csv',[['Employee','Basic salary','HRA 40%','Medical 10%','Estimated gross'],...state.employees.map(e=>[e.name,Number(e.salary)||0,(Number(e.salary)||0)*.4,(Number(e.salary)||0)*.1,(Number(e.salary)||0)*1.5])]);break;case'export-audit':csvDownload('hcm-audit-preview.csv',[['Date','Actor','Action','Detail'],...state.audit.map(a=>[a.date,a.actor,a.action,a.detail])]);break;case'check-in':checkIn();break;case'check-out':checkOut();break;case'date-range':state.dateRange=state.dateRange==='This month'?'Last 30 days':'This month';render();break;case'ai-summary':state.page='AI assistant';state.messages.push({from:'ai',text:`Workspace summary: ${state.employees.length} employees, ${presentToday()} attendance check-ins today, ${pendingLeaves()} pending leave requests, and ${state.announcements.length} announcements. This summary uses browser-local demo data.`});render();break;case'decide-leave':state.leaves=state.leaves.map(l=>l.id===el.dataset.id?{...l,status:el.dataset.status}:l);save('leaves',state.leaves);audit('Leave request '+el.dataset.status,el.dataset.id);render();notify('Leave request '+el.dataset.status.toLowerCase());break;case'delete-employee':if(confirm('Remove this employee from the local demo?')){const e=state.employees.find(x=>x.id===el.dataset.id);state.employees=state.employees.filter(x=>x.id!==el.dataset.id);save('employees',state.employees);audit('Employee removed',e?.name||'');render();notify('Employee removed');}break;case'profile-menu':notify('Role and profile options are demo-only.');break;case'notifications':state.page='Leave management';render();break;case'help':notify('This is a frontend prototype. Backend integration comes next.');break;case'reset-demo':if(confirm('Reset this frontend demo? This clears locally saved workspace data.')){['hcm_company','hcm_setup','hcm_employees','hcm_leaves','hcm_attendance','hcm_announcements','hcm_audit'].forEach(k=>localStorage.removeItem(k));location.reload();}break;case'dismiss-toast':state.toast='';renderToast();break;case'noop':break;}}
  function checkIn(){const me=state.employees[0];if(!me){notify('Register an employee first to try attendance');return;}if(state.attendance.some(a=>a.employeeId===me.id&&a.date===today())){notify('An attendance record already exists for today');return;}const now=new Date();const late=now.getHours()*60+now.getMinutes()>(Number((state.company?.officeStart||'09:00').slice(0,2))*60+Number((state.company?.officeStart||'09:00').slice(3))+Number(state.company?.grace??15));state.attendance.unshift({id:uid(),employeeId:me.id,name:me.name,employeeCode:me.code,date:today(),inTime:now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),outTime:'—',status:late?'Late':'Present'});save('attendance',state.attendance);audit('Employee checked in',me.name);render();notify(me.name+' checked in');}
  function checkOut(){const me=state.employees[0];const r=state.attendance.find(a=>a.employeeId===me?.id&&a.date===today()&&a.outTime==='—');if(!r){notify('No open check-in found for the first employee');return;}r.outTime=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});r.status='Checked out';save('attendance',state.attendance);audit('Employee checked out',me.name);render();notify('Check-out recorded');}
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){state.page=nav.dataset.page;state.mobileOpen=false;state.query='';render();return;}const tab=e.target.closest('[data-leave-tab]');if(tab){state.leaveTab=tab.dataset.leaveTab;render();return;}const prompt=e.target.closest('[data-chat-prompt]');if(prompt){chat(prompt.dataset.chatPrompt);return;}const el=e.target.closest('[data-action]');if(el){action(el.dataset.action,el,e);}});
  document.addEventListener('change',e=>{if(e.target.id==='role-select'){state.role=e.target.value;render();}if(e.target.id==='department-filter'){state.filter=e.target.value;render();}if(e.target.id==='attendance-filter'){const filter=e.target.value;document.querySelectorAll('.table-panel tbody tr').forEach(tr=>{tr.style.display=filter==='All statuses'||tr.textContent.includes(filter)?'':'none';});}});
  document.addEventListener('input',e=>{if(e.target.id==='search-input'){const pos=e.target.selectionStart;state.query=e.target.value;const page=state.page;render();const input=$('#search-input');if(input){input.focus();input.setSelectionRange(pos,pos);}}});
  document.addEventListener('submit',e=>{const form=e.target;if(form.id==='setup-form'){e.preventDefault();const data=formObj(form);if(!data.name.trim()){notify('Please enter your company name');return;}state.company={...initialCompany,...state.settingsForm,...data,grace:Number(data.grace)||0,radius:Number(data.radius)||0,leaveAnnual:Number(data.leaveAnnual??initialCompany.leaveAnnual),leaveSick:Number(data.leaveSick??initialCompany.leaveSick),leaveCasual:Number(data.leaveCasual??initialCompany.leaveCasual)};state.settingsForm={...state.company};save('company',state.company);localStorage.setItem('hcm_setup','yes');state.setupDone=true;audit('Company workspace created',state.company.name);render();notify('Company workspace created');}else if(form.id==='settings-form'){e.preventDefault();const data=formObj(form);state.company={...state.company,...data,grace:Number(data.grace)||0,radius:Number(data.radius)||0,leaveAnnual:Number(data.leaveAnnual)||0,leaveSick:Number(data.leaveSick)||0,leaveCasual:Number(data.leaveCasual)||0};state.settingsForm={...state.company};save('company',state.company);audit('Workspace settings updated',state.company.name);render();notify('Settings saved successfully');}else if(form.id==='employee-form'){e.preventDefault();const data=formObj(form);if(state.employees.some(x=>x.email.toLowerCase()===data.email.toLowerCase()&&x.id!==state.editingEmployee?.id)){notify('This email is already registered');return;}if(state.editingEmployee){state.employees=state.employees.map(x=>x.id===state.editingEmployee.id?{...x,...data,salary:Number(data.salary)||0}:x);audit('Employee updated',data.name);}else{state.employees.push({...data,id:uid(),status:'Active',salary:Number(data.salary)||0,code:'EMP-'+String(state.employees.length+1).padStart(3,'0')});audit('Employee registered',data.name);}save('employees',state.employees);state.modal='';state.editingEmployee=null;render();notify('Employee saved successfully');}else if(form.id==='leave-form'){e.preventDefault();const data=formObj(form);if(data.end<data.start){notify('End date cannot be before start date');return;}state.leaves.unshift({...data,id:uid(),status:'Pending',createdAt:today()});save('leaves',state.leaves);audit('Leave request submitted',data.type+' leave');state.modal='';render();notify('Leave request submitted');}else if(form.id==='announcement-form'){e.preventDefault();const data=formObj(form);state.announcements.unshift({...data,id:uid(),date:today(),author:state.role});save('announcements',state.announcements);audit('Announcement posted',data.title);state.modal='';render();notify('Announcement posted');}else if(form.id==='chat-form'){e.preventDefault();const input=$('#chat-input');if(input)chat(input.value);}});
  render();
})();
